questionvariables.text:
const1:2;
const2:rand([1,1/4,1/9,1/16]);
var1:1;
var2:1;
lower_limit:-sqrt(const2);
upper_limit:sqrt(const2);
aa:expand(((const1-x^2))^2);
dd:int(2*x,x);
fx:const1-x^2;
gx:sqrt(const2-x^2);
ta1:int((((fx)^2-(gx)^2)),x);
ta:int((pi*((fx)^2-(gx)^2)),x,lower_limit,upper_limit);
